function doorParts(d,t){if(d.garage){const step=d.h/4,arc=.52,start=d.h-arc+.04;return Array.from({length:4},(_,i)=>{const travel=(i+.5)*step+t*(start+Math.PI*arc/2+.21),angle=clamp((travel-start)/arc,0,Math.PI/2),centerY=travel<start?travel:start+arc*Math.sin(angle),centerZ=.06+arc*(1-Math.cos(angle))+Math.max(0,travel-start-Math.PI*arc/2);return{id:d.id+'-'+i,x:d.x,y:d.y+centerY-step/2,z:d.z+centerZ,w:d.w,h:step,d:.095,rx:angle,color:C.dark,solid:true,exterior:true,door:true};});}if(d.slide!==undefined){const base=d.axis==='x'?d.x:d.z,leaf=(id,centre,width)=>({id,x:d.axis==='x'?centre:d.x,y:d.y,z:d.axis==='z'?centre:d.z,w:d.axis==='x'?width:.06,h:d.h,d:d.axis==='z'?width:.06,color:C.wood,solid:true,exterior:false,door:true});return d.slide?[leaf(d.id,base+d.slide*t*(d.w-.04),d.w)]:[leaf(d.id+'-a',base-d.w/4-t*(d.w/2-.03),d.w/2),leaf(d.id+'-b',base+d.w/4+t*(d.w/2-.03),d.w/2)];}const sign=d.hinge==='high'?-1:1,hingeX=d.x-(d.axis==='x'?sign*d.w/2:0),hingeZ=d.z-(d.axis==='z'?sign*d.w/2:0),angle=t*Math.PI/2,vx=d.axis==='x'?sign*Math.cos(angle):Math.sin(angle),vz=d.axis==='z'?sign*Math.cos(angle):Math.sin(angle);return[{id:d.id,x:hingeX+vx*d.w/2,y:d.y,z:hingeZ+vz*d.w/2,w:d.w,h:d.h,d:.075,ry:Math.atan2(-vz,vx),color:C.wood,solid:true,exterior:d.exterior,door:true}];}
function doorBounds(p){const cx=Math.abs(Math.cos(p.rx||0)),sx=Math.abs(Math.sin(p.rx||0)),cy=Math.abs(Math.cos(p.ry||0)),sy=Math.abs(Math.sin(p.ry||0)),height=p.h*cx+p.d*sx,depth=p.d*cx+p.h*sx;return{x:p.x,y:p.y+p.h/2-height/2,z:p.z,w:p.w*cy+depth*sy,h:height,d:depth*cy+p.w*sy};}
function overlap(p,a,r=.28,h=1.75){if(p.rx){const b=doorBounds(p);return overlap(b,a,r,h);}if(p.y+p.h<=a.y+.015||p.y>=a.y+h-.015)return false;const c=Math.cos(p.ry||0),s=Math.sin(p.ry||0),dx=a.x-p.x,dz=a.z-p.z,x=dx*c-dz*s,z=dx*s+dz*c;return Math.hypot(Math.max(0,Math.abs(x)-p.w/2),Math.max(0,Math.abs(z)-p.d/2))<r-.00001;}
